fun desk(age: Int) {
    println("desk: start")
    if (age < 0) {
        throw IllegalArgumentException("age cannot be below 0")
    }
    println("desk: end")
}

fun office(age: Int) {
    println("office: start")
    desk(age)
    println("office: end")
}

fun main() {
    println("hall: start")
    office(-5)
    println("hall: end")
}

fun setAge(age: Int): Int {
    require(age >= 0) { "age cannot be below 0" }
    return age
}

fun main() {
    println(setAge(30))
    println(setAge(-5))
    println("done")
}

fun inspect(n: Int) {
    println("looking at " + n)
    if (n < 0) throw IllegalArgumentException("negative")
    println("fine")
}

fun main() {
    inspect(3)
    inspect(-1)
    inspect(5)
}

fun inner() {
    println("inner")
    throw IllegalStateException("boom")
}

fun main() {
    println("main start")
    inner()
    println("main end")
}

